"""Render PDF previews and an offline box-by-box guide to every PPT text box."""
from pathlib import Path
import json,html,base64,zipfile,xml.etree.ElementTree as ET,shutil
import fitz
from PIL import Image,ImageDraw
H=Path(__file__).resolve().parent
slides=json.loads((H/'slide_content.json').read_text());pdf=fitz.open(H/'preview/embodied ai week 32.pdf');assert len(pdf)==len(slides)==35
pre=H/'preview';images=[]
for i,p in enumerate(pdf,1):
 p.get_pixmap(matrix=fitz.Matrix(1.3,1.3),alpha=False).save(pre/f'slide-{i:02d}.png')
 im=Image.open(pre/f'slide-{i:02d}.png');im.thumbnail((480,270));images.append(im.copy())
contact=Image.new('RGB',(1440,300*((len(images)+2)//3)),'#DCE1E5');d=ImageDraw.Draw(contact)
for i,im in enumerate(images):x=(i%3)*480;y=(i//3)*300;contact.paste(im,(x,y+22));d.text((x+12,y+3),str(i+1),fill='black')
contact.save(pre/'contact-sheet.png');shutil.copyfile(pre/'embodied ai week 32.pdf',H/'week32.pdf')
ns={'a':'http://schemas.openxmlformats.org/drawingml/2006/main','p':'http://schemas.openxmlformats.org/presentationml/2006/main'}
esc=html.escape
charts={
 'week32_goal.png':'This is a schematic of the intended behavior, not a simulated rollout. One continuous trial includes a true run, takeoff, flight, landing and resumed running without a reset. The diagram explains what the tests ask for.',
 'training_episodes.png':'Actual saved training mean episode length, converted from policy steps to seconds. A4 is resumed and x=0 is its first saved diagnostic, not its original training start. A5 uses c3. Curves are native training distributions with RSI/randomization, not full L1 passes.',
 'training_errors.png':'Left: episode-mean joint RMS in radians. Right: last-step anchor linear-velocity error in m/s. A1 is omitted because training joint RMS was NOT RECORDED. A4 inherits A2 and adds compute; A5 is a separate reference. These definitions differ from final strict evaluation.',
 'training_curriculum.png':'A1 training duration and the logged end-effector tolerance. The tolerance returns to 0.25 m at update 2000; mean duration shortens. This is a single-run association and final strict L1 stayed 0/20.',

 'nominal.png':'The original command policy passed 20/20 nominal episodes, 16/20 random-timing episodes, and 20/20 repeated-command episodes (40/40 events). Both friction cells passed 20/20. T therefore remains below its 18/20 target.',
 'delay.png':'At 25 ms, composite passes fell to 0/20 while falls stayed 0/20. At 50 ms, all 20 fell. These are baseline command-policy tests, not P09 tests.',
 'landing.png':'Mean/max landing peaks: original bank A 8.77/10.00 BW, candidate 6.27/8.01 BW, original bank B 8.88/10.14 BW. BW means multiples of the simulated body weight. The candidate missed the max-7-BW target; bank B is the original policy evaluated on fresh seeds.',
 'sweep.png':'A1, A3 and A5 completed zero clips; A2 and A4 completed all 20. Every full L1 count is zero. A5 is a c3 variant with a 0.32-second flight gate; it is not pooled with c2. A6 was skipped.',
 'gates.png':'A2/A4 counts: no-fall 18/18; flight 0/0; recovery 10/20; joint-error gate 0/18. Gate margins are not joint passes: only 16 A4 episodes meet all non-flight gates together. No complete test passes.',
 'flight.png':'Solid segments show the range over 20 strict rollouts: A2 0.200–0.225 s and A4 0.195–0.215 s. The gray marker is the kinematic reference’s 0.22-second geometric flight. The red marker is the unchanged physical-flight requirement of 0.24 seconds. Geometric and physical definitions differ.',
 'audit.png':'This image is actual stdout from the presentation builder’s saved-data audit. It is not a fabricated training log, new rollout or demonstration video. The exact output is in audit_output.txt.'}
sections=[];textboxes=0
with zipfile.ZipFile(H/'embodied ai week 32.pptx') as z:
 for i,s in enumerate(slides,1):
  root=ET.fromstring(z.read(f'ppt/slides/slide{i}.xml'));rows=[]
  meaning={s['title']:'Slide purpose: '+s['notes'],s['sub']:'Scope and setup for this slide. '+s['notes'],s['source']:'Evidence pointer. Full local source paths and SHA-256 hashes are in evidence_manifest.json.',s['take']:'The takeaway to say aloud: '+s['notes'],'WEEK 32  ·  SIMULATION ONLY':'This result concerns simulated R1 models. Nothing here demonstrates execution on physical hardware.',f'{i:02d}':'Slide number for navigation.'}
  queues={}
  for b in s['boxes']:
   queues.setdefault(b['title'],[]).append(b['meaning']); queues.setdefault(b['text'],[]).append(b['meaning'])
  for picitem in s.get('pictures',[]):meaning[picitem['label']]='Historical Week 31 frame, included only to explain the starting point. It is not a picture of a new Week 32 policy.'
  for sp in root.findall('.//p:sp',ns):
   paras=sp.findall('p:txBody/a:p',ns);t='\n'.join(''.join(p.itertext()) if False else ''.join(x.text or '' for x in p.findall('.//a:t',ns)) for p in paras).strip()
   if not t:continue
   textboxes+=1;ex=queues[t].pop(0) if queues.get(t) else meaning.get(t,'This is an on-slide label; read it together with the evidence and narration below.')
   rows.append('<div class="box"><blockquote>'+esc(t).replace('\n','<br>')+'</blockquote><p>'+esc(ex)+'</p></div>')
  pic=base64.b64encode((pre/f'slide-{i:02d}.png').read_bytes()).decode()
  fig=('<div class="figure"><strong>Figure explained</strong><p>'+esc(charts[s['chart']])+'</p></div>') if s['chart'] else ('<div class="figure"><strong>Historical images</strong><p>Both pictures are from Week 31: speed-command locomotion and jumping jacks. They illustrate earlier separate skills and are explicitly not Week 32 evidence.</p></div>' if s.get('pictures') else '')
  sections.append(f'<section id="s{i}" class="slide" data-search="{esc((s["title"]+s["sub"]+s["notes"]).lower(),quote=True)}"><header><span>SLIDE {i:02d} / {len(slides)}</span><h2>{esc(s["title"])}</h2></header><img class="preview" alt="Slide {i}: {esc(s["title"],quote=True)}" src="data:image/png;base64,{pic}">{fig}<details open><summary>Box by box · exact PowerPoint wording</summary><div class="colheads"><b>What is on the slide</b><b>What it means</b></div>'+''.join(rows)+'</details><details><summary>What I say aloud</summary><p class="script">'+esc(s['notes'])+'</p></details></section>')
nav=''.join(f'<a href="#s{i}">{i:02d} {esc(s["title"])}</a>' for i,s in enumerate(slides,1))
css='''*{box-sizing:border-box}body{margin:0;background:#f2f5f7;color:#182c40;font:16px/1.65 system-ui,sans-serif}aside{position:fixed;inset:0 auto 0 0;width:280px;background:#182c40;color:white;padding:28px 20px;overflow:auto}aside h1{font-size:24px;line-height:1.2}aside a{display:block;color:#d4e4ed;text-decoration:none;padding:9px 6px;font-size:13px;border-bottom:1px solid #345064}aside a:hover{color:#6de0d0}main{max-width:1250px;margin-left:280px;padding:40px}.intro,.slide{background:white;border:1px solid #dce3e8;border-radius:16px;margin-bottom:30px;padding:28px}.intro h1{font-size:36px;line-height:1.2}.tag,header span{font-size:12px;font-weight:750;letter-spacing:.13em;color:#087f80}h2{font-size:27px;line-height:1.3;margin:10px 0 24px}.preview{display:block;width:100%;border:1px solid #dce3e8;border-radius:7px;margin-bottom:22px}.box{display:grid;grid-template-columns:1fr 1.35fr;border-top:1px solid #dae3e8;gap:24px;padding:15px 0}.box blockquote{margin:0;background:#edf3f4;padding:16px;border-left:3px solid #087f80;white-space:normal}.box p{margin:6px 0}.colheads{display:grid;grid-template-columns:1fr 1.35fr;gap:24px;color:#087f80;margin:20px 0 8px}.figure{background:#eff7f5;border-radius:8px;padding:18px;margin-bottom:20px}details{margin:16px 0}summary{cursor:pointer;font-weight:700}.script{padding:10px 20px;border-left:3px solid #b68428}input{width:100%;padding:12px;border:1px solid #557184;border-radius:7px;margin:12px 0}button{background:#087f80;color:white;border:0;border-radius:6px;padding:11px 17px;margin:5px;cursor:pointer}.hidden{display:none}.gloss{display:grid;grid-template-columns:150px 1fr;gap:12px}.muted{color:#516170;font-size:14px}a{color:#087f80}@media(max-width:950px){aside{position:relative;width:100%;max-height:320px}main{margin:0;padding:16px}.box{grid-template-columns:1fr;gap:2px}.colheads{display:none}.intro,.slide{padding:18px}.intro h1{font-size:28px}}@media print{aside,input,button{display:none}main{margin:0;padding:0}.slide{break-before:page;border:0}.preview{max-width:650px}.box{break-inside:avoid}}'''
gloss=[('L1','The full reference-tracking success contract: complete without a fall/non-foot contact, sufficient physical flight, enough recovery speed, and joint-angle error within both limits. A row needs at least 16/20 full passes.'),('c2 / c3','Two separate repaired motion references. Original c2 uses a 0.24 s flight gate; c3 variant uses its separately anchored 0.32 s gate.'),('RMS','Root mean square joint-angle error, in radians. It measures mismatch over 24 joints; lower is better, but a lower early-terminated average is not proof of full-clip tracking.'),('Body weight (BW)','Landing contact force normalized by the mass and gravity in the specific simulated robot model. It is not an injury or hardware-safety rating.'),('Action delay','A delay in applying the motor position target in the simulation. This is different from delayed observations or real network timing.'),('Seed','A reproducibility setting. Twenty evaluation seeds vary rollouts from one trained checkpoint; they are not twenty independent trained policies.'),('Box-by-box','The left side quotes each PowerPoint text box exactly. The right side explains its meaning and limits. Figures get their own explanations.'),('Video','No new rendered rollout video exists for this sweep. This artifact deliberately presents real numeric charts, not an unrelated old video.')]
intro='<div class="intro"><span class="tag">SHAOQIN LI · WEEK 32 · OCTOBER 31, 2026</span><h1>The box-by-box companion</h1><p>A private, offline guide to the 35-slide presentation: exact slide wording, plain-language explanations and what to say aloud.</p><p><b>Core result:</b> commanded jump 20/20 nominal; best imitation row completed 20/20 clips, but full L1 stayed 0/20.</p><button onclick="toggleAll(true)">Expand all</button><button onclick="toggleAll(false)">Collapse all</button><details><summary>Terms I may need to explain</summary><div class="gloss">'+''.join('<b>'+esc(k)+'</b><span>'+esc(v)+'</span>' for k,v in gloss)+'</div></details><p class="muted">All images and explanations are embedded. No network, account or external library is needed. Private LAFAN-derived media and models are not included.</p></div>'
js="""function toggleAll(v){document.querySelectorAll('details').forEach(d=>d.open=v)}document.getElementById('search').addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.slide').forEach(s=>s.classList.toggle('hidden',!s.textContent.toLowerCase().includes(q)))})"""
(H/'week32_box_by_box.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Week 32 · Box by box · Shaoqin Li</title><style>'+css+'</style></head><body><aside><span class="tag">PRESENTATION GUIDE</span><h1>Week 32<br>Box by box</h1><input id="search" aria-label="Search slides" placeholder="Search a result or term…"><nav>'+nav+'</nav></aside><main>'+intro+''.join(sections)+'</main><script>'+js+'</script></body></html>')
(H/'validation.json').write_text(json.dumps({'slides':len(slides),'rendered_pdf_pages':len(pdf),'explained_ppt_textboxes':textboxes,'offline_html':True,'source':'PowerPoint OOXML text boxes + speaker notes','visual_review':'35-slide context-first revision rendered and visually reviewed'},indent=2))
print('Built offline companion:',len(slides),'slides,',textboxes,'quoted textboxes')
